import {randomUUID} from 'node:crypto';
import {buildResearchMission,MRX_AREAS} from '../../server/research-standard.mjs';
import {mrxCanonical,mrxSha,MRX_RULE} from '../../server/mrx-contract.mjs';
export const NOW=Date.now(),AT=new Date(NOW).toISOString(),PROGRAM='synthetic-mrx-program',RELEASE='synthetic-mrx-release',INDEX='a'.repeat(64),RIGHTS='b'.repeat(64);
export function coverage(programId=PROGRAM){const program={id:programId,name:'SYNTHETIC River Teaching Program',track:'Categorical',registryReleaseId:RELEASE},body={programId,registryReleaseId:RELEASE,observedAt:AT,fields:Object.entries(MRX_AREAS).flatMap(([area,fs])=>fs.map(field=>({area,field,state:['research.curriculum','research.abim','research.visa'].includes(field)?'UNKNOWN':'SUPPORTED'}))).sort((a,b)=>a.field.localeCompare(b.field,'en'))};return {program,coverage:{...body,receipt:{sha256:mrxSha(JSON.stringify(body)),publicRef:'rise-coverage-v1'}}};}
export const mission=()=>buildResearchMission({missionId:randomUUID(),...coverage(),now:NOW});
export function pkg(m=mission()){const p=structuredClone(m.output_template);p.researched_at=AT;p.permitted_use=true;p.execution_declaration={provider:'SYNTHETIC',model:'SYNTHETIC',configuration:'Synthetic no-provider fixture only',completed_at:AT};p.sources=[{id:'curriculum-source',url:'https://teaching.edu/curriculum',title:'SYNTHETIC curriculum',type:'PRIMARY_OFFICIAL',retrieved_at:AT}];p.claims=[{id:'curriculum',area:'curriculum_training',field:'research.curriculum',text:'The program offers a dedicated continuity clinic every Tuesday.',source_ids:['curriculum-source'],confidence:'HIGH',as_of:AT.slice(0,10)}];p.results=p.results.map(r=>r.field==='research.curriculum'?{...r,state:'SUPPORTED',claim_ids:['curriculum'],reason:'Exact cited curriculum statement.'}:{...r,reason:'No supportable public source in the synthetic fixture.'});return p;}
export function review(){return {factsVerified:true,sourceRightsVerified:true,publicProgramOnly:true,sourceAssociationVerified:true,authorityRef:'SYNTHETIC-HUMAN-REVIEW-ONLY',validThrough:new Date(NOW+86400000).toISOString(),reviewedAt:AT};}
export function payload(){return {schema:MRX_RULE,programId:PROGRAM,registryReleaseId:RELEASE,submissionSha256:'c'.repeat(64),claims:[{id:'curriculum',field:'research.curriculum',text:'The program offers a dedicated continuity clinic every Tuesday.',value:{summary:'Dedicated continuity clinic every Tuesday.'},asOf:AT.slice(0,10),sources:[{id:'curriculum-source',url:'https://teaching.edu/curriculum',title:'SYNTHETIC curriculum',retrievedAt:AT}]}],review:review()};}
export function binding(p=payload()){const publicationId=randomUUID();return {intentId:randomUUID(),publicationId,submissionId:randomUUID(),submissionSha256:p.submissionSha256,reviewId:randomUUID(),reviewVersion:2,programId:p.programId,registryReleaseId:p.registryReleaseId,consentId:randomUUID(),adminId:randomUUID(),operation:'publish',idempotencyKey:mrxSha('synthetic:'+publicationId),payloadSha256:mrxSha(mrxCanonical(p)),priorReceiptSha256:'0'.repeat(64)};}
